#include "physics/CCPhysicsRayCast.h"
#if CC_USE_PHYSICS

#include <cmath>
#include <algorithm>
#include <vector>
#include "base/ccMacros.h"
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsWorld.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    // A direction whose squared length is below this is treated as having no direction at all.
    const float RAYCAST_DIRECTION_EPSILON_SQ = 1e-12f;
    const float RAYCAST_TWO_PI = 6.28318530717958647692f;
    // Sentinel returned by distanceToNearestSurface when the ray reaches nothing.
    const float RAYCAST_NO_HIT_DISTANCE = -1.0f;

    // Payload handed to PhysicsRayCast::rayCastAllCallback through cpSpaceSegmentQuery.
    struct RayCastAllContext
    {
        std::vector<RayCastHit>* hits;
        float rayLength;
    };

    void resetHit(RayCastHit* hit)
    {
        if (hit == nullptr)
        {
            return;
        }

        hit->shape = nullptr;
        hit->body = nullptr;
        hit->point = Vec2::ZERO;
        hit->normal = Vec2::ZERO;
        hit->fraction = 0.0f;
        hit->distance = 0.0f;
    }

    bool compareByFraction(const RayCastHit& lhs, const RayCastHit& rhs)
    {
        return lhs.fraction < rhs.fraction;
    }

    // PhysicsWorld does not expose its cpSpace, so it is read back from the first body that
    // already lives in a space. A world that was still empty when init() ran therefore becomes
    // resolvable as soon as it owns a body, which is why callers re-resolve lazily.
    cpSpace* resolveSpace(PhysicsWorld* world)
    {
        if (world == nullptr)
        {
            return nullptr;
        }

        const Vector<PhysicsBody*>& bodies = world->getAllBodies();
        for (const auto& body : bodies)
        {
            if (body == nullptr)
            {
                continue;
            }

            cpBody* cpBodyRef = body->getCPBody();
            if (cpBodyRef == nullptr)
            {
                continue;
            }

            cpSpace* space = cpBodyGetSpace(cpBodyRef);
            if (space != nullptr)
            {
                return space;
            }
        }

        return nullptr;
    }

    cpSpace* activeSpace(PhysicsWorld* world, cpSpace*& cached)
    {
        if (cached == nullptr)
        {
            cached = resolveSpace(world);
        }

        return cached;
    }

    cpShapeFilter buildFilter(unsigned int categories, unsigned int mask, int group)
    {
        // An empty bitmask would reject every shape, so zero is read as "unfiltered".
        cpBitmask filterCategories = (categories == 0) ? CP_ALL_CATEGORIES : static_cast<cpBitmask>(categories);
        cpBitmask filterMask = (mask == 0) ? CP_ALL_CATEGORIES : static_cast<cpBitmask>(mask);

        return cpShapeFilterNew(static_cast<cpGroup>(group), filterCategories, filterMask);
    }

    // Values left at zero in the input fall back to the filter installed by setDefaultFilter.
    cpShapeFilter filterForInput(const RayCastInput& input, unsigned int defaultCategories,
                                 unsigned int defaultMask, int defaultGroup)
    {
        return buildFilter(input.categoryMask != 0 ? input.categoryMask : defaultCategories,
                           input.collisionMask != 0 ? input.collisionMask : defaultMask,
                           input.groupFilter != 0 ? input.groupFilter : defaultGroup);
    }

    // Normalises the direction and clamps the requested length to the configured maximum.
    bool prepareRay(const Vec2& direction, float requestedLength, float maxLength,
                    Vec2* outDirection, float* outLength)
    {
        if (outDirection == nullptr || outLength == nullptr)
        {
            return false;
        }

        *outDirection = Vec2::ZERO;
        *outLength = 0.0f;

        if (requestedLength <= 0.0f)
        {
            return false;
        }

        float directionLengthSq = direction.lengthSquared();
        if (directionLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ)
        {
            return false;
        }

        *outDirection = direction * (1.0f / std::sqrt(directionLengthSq));
        *outLength = (maxLength > 0.0f && requestedLength > maxLength) ? maxLength : requestedLength;

        return true;
    }

    // Single closest hit along origin + direction * length. outHit may be null for existence tests.
    bool segmentFirstHit(cpSpace* space, const Vec2& origin, const Vec2& direction, float length,
                         const cpShapeFilter& filter, RayCastHit* outHit)
    {
        resetHit(outHit);

        if (space == nullptr || length <= 0.0f)
        {
            return false;
        }

        cpSegmentQueryInfo info;
        info.shape = nullptr;
        info.point = cpvzero;
        info.normal = cpvzero;
        info.alpha = 0.0;

        const Vec2 end = origin + direction * length;
        cpShape* cpShapeHit = cpSpaceSegmentQueryFirst(space,
                                                       PhysicsHelper::point2cpv(origin),
                                                       PhysicsHelper::point2cpv(end),
                                                       0.0f,
                                                       filter,
                                                       &info);
        if (cpShapeHit == nullptr)
        {
            return false;
        }

        if (outHit != nullptr)
        {
            PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeHit));
            outHit->shape = physicsShape;
            outHit->body = (physicsShape != nullptr) ? physicsShape->getBody() : nullptr;
            outHit->point = PhysicsHelper::cpv2point(info.point);
            outHit->normal = PhysicsHelper::cpv2point(info.normal);
            outHit->fraction = PhysicsHelper::cpfloat2float(info.alpha);
            outHit->distance = outHit->fraction * length;
        }

        return true;
    }
}

PhysicsRayCast::PhysicsRayCast()
: _world(nullptr)
, _space(nullptr)
, _defaultCategoryMask(0xFFFFFFFF)
, _defaultCollisionMask(0xFFFFFFFF)
, _defaultGroup(0)
, _maxDistance(10000.0f)
, _initialized(false)
{
}

PhysicsRayCast::~PhysicsRayCast()
{
}

bool PhysicsRayCast::init(PhysicsWorld* world)
{
    CCASSERT(world != nullptr, "world shouldn't be nullptr");

    if (world == nullptr)
    {
        return false;
    }

    _world = world;
    // A world without bodies has no reachable cpSpace yet; queries resolve it later on demand.
    _space = resolveSpace(world);
    _initialized = true;

    return true;
}

bool PhysicsRayCast::rayCastFirst(const RayCastInput& input, RayCastHit* outHit)
{
    resetHit(outHit);

    if (!_initialized)
    {
        return false;
    }

    Vec2 direction;
    float length = 0.0f;
    if (!prepareRay(input.direction, input.maxDistance, _maxDistance, &direction, &length))
    {
        return false;
    }

    cpSpace* space = activeSpace(_world, _space);
    if (space == nullptr)
    {
        return false;
    }

    cpShapeFilter filter = filterForInput(input, _defaultCategoryMask, _defaultCollisionMask, _defaultGroup);

    return segmentFirstHit(space, input.origin, direction, length, filter, outHit);
}

int PhysicsRayCast::rayCastAll(const RayCastInput& input, RayCastHit* outHits, int maxHits)
{
    if (outHits == nullptr || maxHits <= 0 || !_initialized)
    {
        return 0;
    }

    Vec2 direction;
    float length = 0.0f;
    if (!prepareRay(input.direction, input.maxDistance, _maxDistance, &direction, &length))
    {
        return 0;
    }

    cpSpace* space = activeSpace(_world, _space);
    if (space == nullptr)
    {
        return 0;
    }

    std::vector<RayCastHit> hits;
    RayCastAllContext context;
    context.hits = &hits;
    context.rayLength = length;

    const Vec2 end = input.origin + direction * length;
    cpShapeFilter filter = filterForInput(input, _defaultCategoryMask, _defaultCollisionMask, _defaultGroup);

    cpSpaceSegmentQuery(space,
                        PhysicsHelper::point2cpv(input.origin),
                        PhysicsHelper::point2cpv(end),
                        0.0f,
                        filter,
                        PhysicsRayCast::rayCastAllCallback,
                        &context);

    // Nearest hit first; a stable sort keeps the collection order of hits sharing a fraction.
    std::stable_sort(hits.begin(), hits.end(), compareByFraction);

    int count = static_cast<int>(hits.size());
    if (count > maxHits)
    {
        count = maxHits;
    }

    for (int i = 0; i < count; ++i)
    {
        outHits[i] = hits[i];
    }

    return count;
}

bool PhysicsRayCast::rayCastAny(const RayCastInput& input)
{
    if (!_initialized)
    {
        return false;
    }

    Vec2 direction;
    float length = 0.0f;
    if (!prepareRay(input.direction, input.maxDistance, _maxDistance, &direction, &length))
    {
        return false;
    }

    cpSpace* space = activeSpace(_world, _space);
    if (space == nullptr)
    {
        return false;
    }

    cpShapeFilter filter = filterForInput(input, _defaultCategoryMask, _defaultCollisionMask, _defaultGroup);

    // Existence test only: the closest hit is enough and no result is written back.
    return segmentFirstHit(space, input.origin, direction, length, filter, nullptr);
}

bool PhysicsRayCast::rayCastClosest(const Vec2& origin, const Vec2& end, RayCastHit* outHit)
{
    Vec2 delta = end - origin;

    RayCastInput input;
    input.origin = origin;
    input.direction = delta;
    input.maxDistance = delta.length();
    input.categoryMask = _defaultCategoryMask;
    input.collisionMask = _defaultCollisionMask;
    input.groupFilter = _defaultGroup;

    return rayCastFirst(input, outHit);
}

int PhysicsRayCast::rayCastMultiple(const Vec2& origin, const Vec2& end, RayCastHit* outHits, int maxHits)
{
    Vec2 delta = end - origin;

    RayCastInput input;
    input.origin = origin;
    input.direction = delta;
    input.maxDistance = delta.length();
    input.categoryMask = _defaultCategoryMask;
    input.collisionMask = _defaultCollisionMask;
    input.groupFilter = _defaultGroup;

    return rayCastAll(input, outHits, maxHits);
}

int PhysicsRayCast::fanRayCast(const Vec2& origin, const Vec2& direction, float angle, int numRays,
                               float maxDistance, RayCastHit* outHits, int maxHits)
{
    if (outHits == nullptr || maxHits <= 0 || numRays <= 0 || !_initialized)
    {
        return 0;
    }

    Vec2 centreDirection;
    float length = 0.0f;
    if (!prepareRay(direction, maxDistance, _maxDistance, &centreDirection, &length))
    {
        return 0;
    }

    cpSpace* space = activeSpace(_world, _space);
    if (space == nullptr)
    {
        return 0;
    }

    cpShapeFilter filter = buildFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);

    // The sweep is symmetric around the centre direction: a single ray fires straight ahead,
    // otherwise the rays run from -angle/2 to +angle/2 in equal steps.
    float centreAngle = centreDirection.getAngle();
    float step = (numRays > 1) ? angle / static_cast<float>(numRays - 1) : 0.0f;
    float firstAngle = (numRays > 1) ? centreAngle - angle * 0.5f : centreAngle;

    int found = 0;
    for (int i = 0; i < numRays && found < maxHits; ++i)
    {
        Vec2 rayDirection = Vec2::forAngle(firstAngle + step * static_cast<float>(i));

        RayCastHit hit = {};
        if (segmentFirstHit(space, origin, rayDirection, length, filter, &hit))
        {
            outHits[found] = hit;
            ++found;
        }
    }

    return found;
}

int PhysicsRayCast::circleRayCast(const Vec2& center, float radius, int numRays,
                                  RayCastHit* outHits, int maxHits)
{
    if (outHits == nullptr || maxHits <= 0 || numRays <= 0 || !_initialized)
    {
        return 0;
    }

    Vec2 firstDirection;
    float length = 0.0f;
    if (!prepareRay(Vec2::UNIT_X, radius, _maxDistance, &firstDirection, &length))
    {
        return 0;
    }

    cpSpace* space = activeSpace(_world, _space);
    if (space == nullptr)
    {
        return 0;
    }

    cpShapeFilter filter = buildFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);

    // Rays are spread evenly over the full turn, so the last one stops just short of the first.
    float step = RAYCAST_TWO_PI / static_cast<float>(numRays);

    int found = 0;
    for (int i = 0; i < numRays && found < maxHits; ++i)
    {
        Vec2 rayDirection = Vec2::forAngle(step * static_cast<float>(i));

        RayCastHit hit = {};
        if (segmentFirstHit(space, center, rayDirection, length, filter, &hit))
        {
            outHits[found] = hit;
            ++found;
        }
    }

    return found;
}

bool PhysicsRayCast::lineOfSight(const Vec2& from, const Vec2& to, unsigned int obstacleMask)
{
    if (!_initialized)
    {
        return false;
    }

    cpSpace* space = activeSpace(_world, _space);
    if (space == nullptr)
    {
        // No space to query means there is nothing that could block the segment.
        return true;
    }

    Vec2 delta = to - from;
    Vec2 direction;
    float length = 0.0f;
    if (!prepareRay(delta, delta.length(), _maxDistance, &direction, &length))
    {
        // Both ends coincide, so the target is trivially visible.
        return true;
    }

    cpShapeFilter filter = buildFilter(_defaultCategoryMask,
                                       obstacleMask != 0 ? obstacleMask : _defaultCollisionMask,
                                       _defaultGroup);

    return !segmentFirstHit(space, from, direction, length, filter, nullptr);
}

float PhysicsRayCast::distanceToNearestSurface(const Vec2& origin, const Vec2& direction, float maxDist)
{
    if (!_initialized)
    {
        return RAYCAST_NO_HIT_DISTANCE;
    }

    Vec2 rayDirection;
    float length = 0.0f;
    if (!prepareRay(direction, maxDist, _maxDistance, &rayDirection, &length))
    {
        return RAYCAST_NO_HIT_DISTANCE;
    }

    cpSpace* space = activeSpace(_world, _space);
    if (space == nullptr)
    {
        return RAYCAST_NO_HIT_DISTANCE;
    }

    cpShapeFilter filter = buildFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);

    RayCastHit hit = {};
    if (!segmentFirstHit(space, origin, rayDirection, length, filter, &hit))
    {
        return RAYCAST_NO_HIT_DISTANCE;
    }

    return hit.distance;
}

void PhysicsRayCast::setDefaultFilter(unsigned int categoryMask, unsigned int collisionMask, int group)
{
    _defaultCategoryMask = categoryMask;
    _defaultCollisionMask = collisionMask;
    _defaultGroup = group;
}

void PhysicsRayCast::setMaxRayCastDistance(float maxDist)
{
    if (maxDist <= 0.0f)
    {
        CCLOG("PhysicsRayCast WARNING: max raycast distance must be positive, keeping %f", _maxDistance);
        return;
    }

    _maxDistance = maxDist;
}

float PhysicsRayCast::computeReflectionAngle(const Vec2& inDirection, const Vec2& normal)
{
    Vec2 reflected = computeReflectionDirection(inDirection, normal);
    if (reflected.lengthSquared() <= RAYCAST_DIRECTION_EPSILON_SQ)
    {
        return 0.0f;
    }

    return reflected.getAngle();
}

Vec2 PhysicsRayCast::computeReflectionDirection(const Vec2& inDirection, const Vec2& normal)
{
    float normalLengthSq = normal.lengthSquared();
    if (normalLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ)
    {
        // Without a surface normal there is nothing to mirror against.
        return inDirection;
    }

    Vec2 unitNormal = normal * (1.0f / std::sqrt(normalLengthSq));

    // Mirror law r = d - 2 * (d . n) * n, which keeps the length of the incoming direction.
    return inDirection - unitNormal * (2.0f * inDirection.dot(unitNormal));
}

Vec2 PhysicsRayCast::computeRefractionDirection(const Vec2& inDirection, const Vec2& normal, float ratio)
{
    float directionLengthSq = inDirection.lengthSquared();
    if (directionLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ)
    {
        return Vec2::ZERO;
    }

    Vec2 incident = inDirection * (1.0f / std::sqrt(directionLengthSq));

    float normalLengthSq = normal.lengthSquared();
    if (normalLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ || ratio <= 0.0f)
    {
        // No surface or no usable index ratio: the ray keeps travelling unbent.
        return incident;
    }

    Vec2 unitNormal = normal * (1.0f / std::sqrt(normalLengthSq));

    float cosIncident = incident.dot(unitNormal);
    if (cosIncident > 0.0f)
    {
        // The normal points along the ray, so flip it to face the incoming side.
        unitNormal = -unitNormal;
        cosIncident = -cosIncident;
    }

    // Snell's law in vector form with ratio = n1 / n2.
    float k = 1.0f - ratio * ratio * (1.0f - cosIncident * cosIncident);
    if (k < 0.0f)
    {
        // Total internal reflection: the ray bounces off instead of crossing the surface.
        return computeReflectionDirection(incident, unitNormal);
    }

    return incident * ratio - unitNormal * (ratio * cosIncident + std::sqrt(k));
}

void PhysicsRayCast::rayCastAllCallback(cpShape* shape, cpVect point, cpVect normal,
                                        cpFloat alpha, void* data)
{
    RayCastAllContext* context = static_cast<RayCastAllContext*>(data);
    if (shape == nullptr || context == nullptr || context->hits == nullptr)
    {
        return;
    }

    PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(shape));

    RayCastHit hit;
    hit.shape = physicsShape;
    hit.body = (physicsShape != nullptr) ? physicsShape->getBody() : nullptr;
    hit.point = PhysicsHelper::cpv2point(point);
    hit.normal = PhysicsHelper::cpv2point(normal);
    hit.fraction = PhysicsHelper::cpfloat2float(alpha);
    hit.distance = hit.fraction * context->rayLength;

    context->hits->push_back(hit);
}

NS_CC_END

#endif // CC_USE_PHYSICS

